from fastapi import APIRouter, Depends, HTTPException
from celery.result import AsyncResult
from celery import Celery

router = APIRouter(prefix="/celery/periodic-results")

@router.get("/{task_id}")
async def get_periodic_task_result(
    task_id: str,
    celery_app: Celery = Depends(get_celery_app),
    meta_repo: TaskExecutionRepo = Depends(get_task_execution_repo),
    current_user: User = Depends(get_current_user)
):
    execution = await meta_repo.get_task_record(task_id)
    if not execution or execution.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=404, detail="Task result not found")

    result = AsyncResult(task_id, app=celery_app)
    if not result.ready():
        return {"task_id": task_id, "status": result.status, "ready": False}

    return {
        "task_id": task_id,
        "status": result.status,
        "ready": True,
        "result": result.result
    }
